const e = $input.first().json;
const wf = e.workflow?.name ?? 'unknown workflow';
const node = e.execution?.lastNodeExecuted ?? 'unknown node';
const msg = e.execution?.error?.message ?? 'unknown error';
const alert = `LENDLOOP AUTOMATION FAILED\nWorkflow: ${wf}\nNode: ${node}\nError: ${msg}\nExecution: ${e.execution?.url ?? e.execution?.id}`;
// MOCK ALERT: visible in this execution's output and in n8n logs.
// Replace with Email / Slack / Discord node for a real alert.
console.error(alert);
return [{ json: { channel: 'mock-alert', alert } }];
